    const hasTrial = !!(trialInWeek && isoAdd(wk.startIso, i).toISOString().slice(0, 10) === SCHEDULED_TRIAL.iso);
    if (ds.length || hasTrial) days.push({ i: i, dn: dn, ds: ds, trial: hasTrial });
