/** 4.5s a slide — the design's own figure, and the same value the progress keyframe uses. */
const COMM_STORY_MS = 4500;
/** ⚠️ THE STORY'S OWN SHAPE, roughly 9:16 — the frame a phone story occupies. Read by the call that draws
 *  the route AND written into the element's aspect-ratio, so the two cannot disagree. */
const STORY_ART_W = 360, STORY_ART_H = 620;
/**
 * THE ONE META LINE: what they are training for, what they are running in, and this week's distance.
 *
 * ⚠️ THESE WERE THREE ROWS OF THREE DIFFERENT SHAPES — a bold label and text, a shoe row using
 * space-between for two short items (so it left a gap the width of the card), and a lone grey capsule.
 * They are all small facts about right now, so they read better as one line that wraps naturally than
 * as three competing blocks. (Separated by spacing alone — see the note at the return.)
 * ⚠️ THE SHOE KEEPS ITS LINK AND ITS OWN MILEAGE. The link is the runner's own typed URL (his
 * instruction: hyperlinked if they add where they bought them), and the two distances stay apart — the
 * shoe's total belongs beside the shoe, the week's belongs to the week. Side by side in the old layout
 * they were two unlabelled kilometre figures a row apart, which is its own confusion.
 */
function commMetaLine(forLine, tr, shopHref, wk) {
  const bits = [];
  if (forLine) bits.push('<span class="cm-mi"><b>Training for</b> ' + esc(forLine) + '</span>');
  if (wk && wk.km > 0) {
    bits.push('<span class="cm-mi num">' + commKm(wk.km) + ' this week</span>');
  }
  // ⚠️ HIS RULING, 2026-08-23: "the trainer information needs to be underneath the distance covered this
  // week on its own line." So it comes LAST and .cm-mi-shoe takes a whole row to itself — the order here
  // and the full-row basis in the stylesheet are one decision, and changing either alone puts the shoes
  // back beside something.
  if (tr) {
    bits.push('<span class="cm-mi cm-mi-shoe">' + ICON.shoe +
      (shopHref
        // ⚠️ rel="noopener noreferrer" AND target — a link the runner typed opens away from the app, and
        // the page it lands on must never be handed a handle back to this one.
        ? '<a href="' + esc(shopHref) + '" target="_blank" rel="noopener noreferrer">' +
          esc(tr.name) + '</a>'
        : esc(tr.name)) +
      ' <span class="num">' + Math.round(tr.km) + ' km</span></span>');
  }
  if (!bits.length) return "";
  // ⚠️⚠️ NO SEPARATOR GLYPH AT ALL, AND BOTH OTHER VERSIONS WERE TRIED ON THE SERVED PAGE. A dot as its
  // own span is a flex item, so a wrap left it stranded at the end of the first line ("week 1 of 36 ·");
  // moved to a ::before on the following item, the wrap carried it down and it LED the second line,
  // which reads as a bullet list. A separator and a wrapping row do not mix. Spacing alone cannot
  // strand, and at this size and colour the items read as separate without a glyph between them.
  return '<div class="cm-meta">' + bits.join("") + '</div>';
}
function viewCommunity() {
  const v = commView();
  const p = commProfile();
  const bests = commBests();
  const wk = logTotals(logWeekStartIso(), todayIso());
  const uploads = clubPosts();
  const stories = clubStories();
  // ⚠️ POSTS COUNTS WHAT THE RUNNER HAS PUT UP, NOT HOW MANY TIMES THEY HAVE RUN. Before there was
  // anything to post, the run count was the only honest thing that number could be; now that a post is
  // a real object, counting runs there would be a figure that never matches the grid beneath it.
  const posts = uploads.length;
  const story = commStory();

  const avatar = p.avatar
    ? '<img src="' + esc(p.avatar) + '" alt="">'
    : '<span class="cm-init">' + esc(p.initials) + '</span>';
  // ⚠️ THE RING AND THE BADGE ONLY EXIST IF THERE IS A STORY TO OPEN. An unseen-story ring over nothing
  // is a control that looks live and does nothing.
  // ⚠️ THE RING IS LIVE WHEN THERE IS SOMETHING TO OPEN, and the + is ALWAYS live — it is the owner's
  // fourth screenshot, and its whole job is to be there when there is no story yet.
  // ⚠️ THE + IS A SIBLING OF THE RING, NOT A CHILD OF IT. Nested, a tap on the badge would bubble to
  // the ring and open the story viewer instead of the camera roll — a control that looks like one thing
  // and does another, which is the defect class this app has shipped three times.
  const anyStory = stories.length > 0 || !!story;
  const ring = '<span class="cm-avwrap">' +
    (anyStory
      ? '<button class="cm-av cm-av-story" data-cstory="1" aria-label="Open your story">' + avatar + '</button>'
      : '<span class="cm-av">' + avatar + '</span>') +
    '<button class="cm-avplus" data-cadd="story" aria-label="Add to your story">' + ICON.plusDot +
    '</button></span>';

  const stat = (n, label, action) => {
    const inner = '<span class="cm-stat-v num">' + esc(String(n)) + '</span>' +
      '<span class="cm-stat-k">' + label + '</span>';
    return action
      ? '<button class="cm-stat" data-csheet="' + action + '">' + inner + '</button>'
      : '<span class="cm-stat">' + inner + '</span>';
  };

  // ⚠️ A TYPED PB SAYS PB; A COMPUTED ONE SAYS BEST. Two words because they are two different claims —
  // one is a race result the runner is telling us about, the other is the quickest the app has recorded
  // them covering about that far, training runs included.
  const cp = loadClubProf();
  const chips = clubChips().map((b) =>
    '<span class="cm-chip cm-chip-acc num">' + (b.pb ? "PB" : "Best") + ' · ' + b.label + ' ' +
    b.time + '</span>').join("");
  const tr = clubTrainers();
  const shopHref = tr ? clubShopHref(tr.shop) : "";
  const forLine = clubTrainingFor();

  // ⚠️ TWO KINDS OF TILE IN ONE GRID, AND THE FILTER MEANS DIFFERENT THINGS TO EACH. "Videos" keeps
  // the posted clips and drops everything else — a run is not a video, so under Videos the run tiles go
  // rather than being shown as though they were films of themselves.
  const which = clubMediaTab();
  const vidOnly = which === "video", logOnly = which === "logbook";
  const shown = vidOnly ? uploads.filter((u) => u.video)
    : logOnly ? uploads.filter((u) => u.logbook) : uploads;
  const anyLog = uploads.some((u) => u.logbook);
  const tabs = uploads.length ? clubTabsHtml(anyLog) : "";
  const head = logOnly ? "Logbook" : "Posted";
  const unit = vidOnly ? (shown.length === 1 ? " VIDEO" : " VIDEOS")
    : logOnly ? (shown.length === 1 ? " ENTRY" : " ENTRIES")
    : (shown.length === 1 ? " POST" : " POSTS");
  const upGrid = shown.length
    ? '<div class="cm-mhead"><h2>' + head + '</h2><span class="num">' + shown.length + unit +
      '</span></div><div class="cm-grid">' + shown.map(clubTileHtml).join("") + '</div>'
    : ((vidOnly || logOnly) && uploads.length
        // ⚠️ THE ADDENDUM'S OWN LINE, and it is the honest one: a quiet sentence beats an empty
        // three-column area that reads as the app having lost something.
        ? '<div class="cm-empty cm-empty-sm"><p>' + (logOnly
            ? 'No logbook entries yet — write how a run felt on its own page and you can save it here.'
            : 'No videos yet — anything you film on a run shows up here.') + '</p></div>' : "");
  // ⚠️⚠️ THE GRID IS WHAT HE HAS CHOSEN TO POST, AND NOTHING ELSE. It used to be every run the app had
  // ever recorded, put there by the app — which is a training log wearing a profile's clothes, and the
  // Logbook already is the log. His instruction: "I want the user to decide what to post on their grid,
  // not for it to be automatically added". So the months of runs are gone from here entirely; a run
  // reaches the grid by being shared to it, from the run's own page or automatically if he asks for that.
  const grid = tabs + upGrid + (uploads.length ? "" :
    '<div class="cm-empty cm-empty-sm"><p>Nothing posted yet. Finish a run and you can put it here ' +
    'from its own page — or turn on automatic posting in Edit profile and every run goes up.</p>' +
    '<button class="ui-btn" data-cedit="1">Edit profile</button></div>');

  return '<div class="cm-wrap">' +
    '<div class="cm-seg" role="tablist">' +
      '<span class="cm-thumb' + (v === "feed" ? " r" : "") + '"></span>' +
      '<button role="tab" aria-selected="' + (v === "mine") + '" data-cgo="mine">Your runs</button>' +
      '<button role="tab" aria-selected="' + (v === "feed") + '" data-cgo="feed">Feed</button>' +
    '</div>' +
    '<div class="cm-vp"><div class="cm-track' + (v === "feed" ? " feed" : "") + '" id="cmTrack">' +
      '<section class="cm-pane">' +
        '<div class="cm-head">' + ring +
          '<div class="cm-stats">' +
            stat(posts, "Posts", "") +
            stat(0, "Followers", "followers") +
            stat(0, "Following", "following") +
          '</div>' +
        '</div>' +
        // ⚠️⚠️ REGROUPED TO HIS ASK: "Redesign this section so that it fits nicely, it looks cluttered".
        // It was SEVEN left-aligned rows of unequal weight, each a different kind of thing, all at full
        // width and all competing — name, handle, bio, training-for, shoe, a wrapping row of PB
        // capsules, and the week's distance alone on a row in a DIFFERENT capsule style, which read as a
        // fifth PB that had failed to render.
        //
        // Now three tiers, and the count is the point:
        // ⚠️ 1. IDENTITY ON ONE LINE. The name and the handle are one fact about one person, so they
        //    share a line — bold then muted — rather than stacking into two rows of near-equal weight.
        // ⚠️ 2. ONE META LINE FOR THE FACTS. What they are training for, the shoes they are in, and the
        //    week's distance are all small facts about right now, so they are one dot-separated line
        //    that wraps as prose instead of three rows of three different shapes. This is what kills
        //    the odd grey capsule: the week's distance was the only thing on the card wearing a capsule
        //    it did not share with anything else.
        // ⚠️ 3. THE TIMES SCROLL IN ONE ROW. Four PBs wrapped to two lines and orphaned the fourth, and
        //    the "TIMES" label was taking width from the very row that could not fit. A single
        //    horizontal scroller never wraps, however many distances the runner fills in — and the
        //    label moves above it where it costs the capsules nothing.
        '<div class="cm-id">' +
          (p.name || cp.username
            ? '<div class="cm-idline">' +
                (p.name ? '<span class="cm-name">' + esc(p.name) + '</span>' : "") +
                (cp.username ? '<span class="cm-at">@' + esc(cp.username) + '</span>' : "") +
              '</div>'
            : "") +
          (cp.bio ? '<div class="cm-bio">' + esc(cp.bio) + '</div>' : "") +
          commMetaLine(forLine, tr, shopHref, wk) +
          (chips
            ? '<div class="cm-times"><span class="cm-eyebrow">Times</span>' +
              '<div class="cm-pbrow">' + chips + '</div></div>'
            : "") +
        '</div>' +
        '<div class="cm-acts">' +
          '<button class="cm-act" data-cedit="1">Edit profile</button>' +
          // ⚠️ "Create a post", not "Share a run" — his instruction. Sharing a run is not lost: it lives
          // on the run's own page as "Share my run", which is where it always has, and is the only place
          // a run can be picked to share from. This button is now about putting something new up.
          '<button class="cm-act cm-act-pri" data-cnewpost="1">Create a post</button>' +
        '</div>' +
        commJournalRailHtml() +
        grid +
      '</section>' +
      '<section class="cm-pane">' +
        // ⚠️⚠️ THE FEED IS THE EMPTY STATE AND NOTHING ELSE — his instruction: "it shouldn't look like
        // that, it will be empty until there are other users posting". The stories rail was here because
        // the design puts one on the feed, and with nobody to follow it held only the runner's own story
        // beside an Add button — a row of two things above a message saying there is nothing to show.
        // ⚠️ AND NOTHING IS LOST BY REMOVING IT: the avatar on the other pane already opens his story and
        // its + badge already adds one, so both routes survive on the screen that is about him.
        // ⚠️ IT ALSO RENDERED WRONGLY, and that is worth recording rather than fixing invisibly:
        // .cm-rail-ring img set a font-size and a colour and never sized or clipped the image, so the
        // avatar came out at its natural size spilling across the screen. The rule was written for the
        // initials span and the img selector was bolted onto it without giving it dimensions.
        commFeedHtml() +
      '</section>' +
    '</div></div>' +
  '</div>';
}

// ============ SUPPORT ======================================================
