  if (!/^\\d{1,2}:[0-5]\\d$/.test(raw)) { el.textContent = ""; return; }
  const s = RC.parseDuration(raw);
  if (s < RC.TWO_KM_RULES.minSeconds || s > RC.TWO_KM_RULES.maxSeconds) { el.textContent = ""; return; }
