  const cx = Math.cos((Number(route[0].lat) || 0) * Math.PI / 180) || 1;
  const X = route.map((p) => (Number(p.lng) || 0) * 111320 * cx);
  const Y = route.map((p) => (Number(p.lat) || 0) * 111132);
  const sig = new Float64Array(n);
