  // one size and wrong for every other, and the failure is a line running off the edge of a picture
  // somebody has posted.
  g.fillStyle = "#fff";
  const size = Math.round(S * 0.048);
  g.font = "500 " + size + "px " + CLUB_TILE_FONT;
